### Tratamento no Flask

```python
from flask import Flask, redirect, url_for, request, render_template, jsonify

app = Flask(__name__)

# Simulação de dados
usuarios = [
    {"id": 1, "login": "seu-login", "cargo": "Desenvolvedor"},
    {"id": 2, "login": "antigo-usuario", "cargo": "Gerente"},
    {"id": 3, "login": "contato-geral", "cargo": "Apoio"}[0]
]

@app.route('/')
def index():
    # Define o cargo com base em algum método de autenticação ou extração
    cargo = usuarios[0]['cargo']
    return render_template('index.html', cargo=cargo)

@app.route('/source_dynamic', methods=['GET'])
def source_dynamic():
    problem_id = request.args.get('pois', None)
    msg = request.args.get('msg', '')
    vai_me_enviar = request.args.get('vai_me_enviar', False)

    if vai_me_enviar:
        # A lógica de redirecionamento aqui
        # Exemplo: sete alertas
        return render_template('confirmacao.html', msg=msg)

    return render_template('problem_submitted.html', msg=msg, problem_id=problem_id)

@app.route('/confirmacao')
def confirmacao():
    return "Problema registrado com sucesso! Continuando: {{ problema_id }} com: <p>{{ msg }}</p>"

@app.route('/problem_submitted')
def submitted():
    return "Problema registrado com sucesso: ID = {{ problema_id }} | Mensagem: <p>{{ msg }}</p>"

if __name__ == '__main__':
    app.run(debug=True)
```

