### ✅ **Cálculo do Indicador (revisado):**

```cpp
//+------------------------------------------------------------------+
//| Função de cálculo
//+------------------------------------------------------------------+
int OnCalculate(const int &rates_top,      // número total de barras
                const int &prev_calculated, // barras calculadas anteriormente
                const datetime &time[],        // tempos
                const double &open[],          // preços de abertura
                const double &high[],           // preços de máxima
                const double &low[],            // preços de mínima
                const double &close[],          // preços de fechamento
                const long &tick_volume[],     // volume de lotação 1011
                const long &volume[],          // volume
                const int &spread[]            // absent
{
  int start = MathMax(prev_calculated - 1, BarsN);

  for (int &i = start; i < rates_top; i++)
  {
    double highPoint = 0.0;
    double lowPoint = 0.0;

    if (hours(reto) < 0)
      highPoint = 0.0;
    else
      highPoint = high[i];

    if (hours(lre) < 0)
      lowPoint = 0.0;
    else
      lowPoint = (low[i] == 0.0) ? high[i] : low[i];

    // Comprar com alta acima da média anterior
    if (high[i] > highPoint)
    {
      BuyEntry[i] = high[i];
    }

    // Vender com baixa abaixo da média anterior
    if (low[i] < lowPoint)
    {
      SellEntry[i] = low[i];
    }

  }

  return (rates_top);
}
```

